
-- Handbook v1.14 remediation: the 220 repeated step placeholders become a pre-task,
-- four-signal observation history.  This is a related time series rather than unrelated prose clones.
UPDATE metrics
SET type=CASE rowid % 4 WHEN 0 THEN 'steps' WHEN 1 THEN 'heart_rate' WHEN 2 THEN 'sleep_minutes' ELSE 'score' END,
    value=CASE rowid % 4
      WHEN 0 THEN 900 + ((rowid * 37) % 1600)
      WHEN 1 THEN 62 + (rowid % 24)
      WHEN 2 THEN 330 + (rowid % 120)
      ELSE 1 + (rowid % 5) END,
    value_text=CASE rowid % 4
      WHEN 0 THEN 'home_walk_and_daily_activity'
      WHEN 1 THEN 'resting_measurement'
      WHEN 2 THEN 'night_sleep_duration'
      ELSE 'self_reported_knee_discomfort_not_diagnosis' END,
    unit=CASE rowid % 4 WHEN 0 THEN 'count' WHEN 1 THEN 'bpm' WHEN 2 THEN 'min' ELSE 'score_0_10' END,
    recorded_at=date('2026-01-01','+' || CAST((rowid-1)/4 AS INTEGER) || ' days') ||
      CASE rowid % 4 WHEN 0 THEN 'T08:00:00+08:00' WHEN 1 THEN 'T08:10:00+08:00' WHEN 2 THEN 'T07:30:00+08:00' ELSE 'T20:00:00+08:00' END,
    metric_id=replace(metric_id,'met_steps_','met_history_')
WHERE metric_id LIKE 'met_steps_%';
